CREATE TABLE admin_jobs (id VARCHAR(120) PRIMARY KEY, job_type VARCHAR(80) NOT NULL, actor_id VARCHAR(120) NOT NULL, payload_json JSONB NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', total_count INT NOT NULL, success_count INT NOT NULL DEFAULT 0, failure_count INT NOT NULL DEFAULT 0, attempts INT NOT NULL DEFAULT 0, last_error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), started_at TIMESTAMPTZ, completed_at TIMESTAMPTZ);
CREATE TABLE admin_job_items (id BIGSERIAL PRIMARY KEY, job_id VARCHAR(120) NOT NULL, item_key VARCHAR(160) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', attempts INT NOT NULL DEFAULT 0, last_error TEXT, updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(job_id,item_key));
CREATE TABLE admin_outbox_events (id VARCHAR(120) PRIMARY KEY, aggregate_type VARCHAR(80) NOT NULL, aggregate_id VARCHAR(120) NOT NULL, event_type VARCHAR(120) NOT NULL, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), correlation_id VARCHAR(120) NOT NULL, payload_json JSONB NOT NULL, published_at TIMESTAMPTZ);
CREATE INDEX admin_job_status_idx ON admin_jobs(status,created_at);
CREATE INDEX admin_job_item_idx ON admin_job_items(job_id,status,updated_at);
